                var r = d['round' + p];
                if (r) { for (k in r) { if (Object.prototype.hasOwnProperty.call(r, k)) { out[k] = r[k]; } } }
            }
            return out;
        }

        _active(dec, period, g) {
            if (this.ROUND_OF[g] <= period) {
                var v = dec[g];
                return (v === undefined || v === null) ? this.DEFAULTS[g] : v;
            }
            return this.REF[g];
        }

        _semester(dec, k) {
            var c = this.C;
            var per = [];
            var a1 = {};
            var i, p;
            for (i = 0; i < this.KEYS.length; i++) { a1[this.KEYS[i]] = this._active(dec, 1, this.KEYS[i]); }
            var od = this.ORDER[a1.order1];
            var oUnits = od[0], oCost = od[1], oFit = od[2], oCtrl = od[3];
            var good = oUnits * oFit;
            var bad = oUnits - good;
            var cgood = 0.0;
            var ctrl = c.CTRL0;
            var apparel = a1.order1 !== 'none';
            for (p = 1; p <= 4; p++) {
                var a = {};
                for (i = 0; i < this.KEYS.length; i++) { a[this.KEYS[i]] = this._active(dec, p, this.KEYS[i]); }
                var pr = this.PRICE[a.price1];
                var mx = (p >= 2) ? this.MIX[a.mix2] : this.MIX.same;
                var cs = (p >= 2) ? this.CASH[a.cash2] : this.CASH.weekly;
                var sh = (p >= 3) ? this.SHRINK[a.shrink3] : this.SHRINK.ignore;
                var rs = (p >= 3) ? this.RESTOCK[a.restock3] : [0.0, 1.0, 0.0];
                var pm = (p === 4) ? this.PROMO[a.promo4] : this.PROMO.none;
                var clCtrl = (p === 4) ? this.CLOSE[a.close4] : 0.0;
                var resp = 1.0 + c.CTRL_SENS * (ctrl - c.CTRL0);
                if (p === 3 && apparel && a.restock3 !== 'none') {
                    var rUnits = (rs[0] === null) ? oUnits : rs[0];
                    if (a.restock3 === 'consign') {
                        cgood += rUnits * rs[1];
                    } else {
                        var fit = (rs[1] === null) ? oFit : rs[1];
                        good += rUnits * fit;
                        bad += rUnits * (1 - fit);
                    }
                }
                var sUnits = c.SNACK_U * c.DAYS * pr[1] * mx[0] * sh[1] * pm[2] * resp;
                var sSales = sUnits * pr[0] * pm[3];
                var sCogs = sUnits * c.SNACK_COST * (1 + mx[1]);
                var dem = apparel ? c.APP_DEMAND[p - 1] * pr[3] * sh[1] * pm[4] * resp : 0.0;
                var uOwn = Math.min(dem, good);
                var uCon = Math.min(dem - uOwn, cgood);
                good -= uOwn;
                cgood -= uCon;
                var aUnits = uOwn + uCon;
                var aSales = aUnits * pr[2] * pm[5];
                var aCogs = uOwn * oCost + uCon * c.CONSIGN_COST;
                var pre = pm[0] * resp;
                var preSales = pre * c.PRE_PRICE;
                var preCogs = pre * c.APP_COST;
                var clr = bad * pm[1];
                var clrSales = clr * oCost;
                bad -= clr;
                var sales = sSales + aSales + preSales + clrSales;
                var cogs = sCogs + aCogs + preCogs + clrSales;
                var baseSh = c.SHRINK0 + ((p === 4) ? c.SHRINK_P4 : 0.0);
                var shRate = (sh[0] === null) ? baseSh : sh[0];
                var shrink = shRate * (sSales + aSales);
                var cashLoss = cs[0] * c.CASH_SHARE * sales;
                var left = (p === 4) ? (good + bad) : 0.0;
                var writedown = (p === 4) ? left * oCost * c.WRITEDOWN : 0.0;
                var fixed = c.FIXED + ((p === 3) ? sh[2] : 0.0);
                var profit = sales - cogs - shrink - cashLoss - writedown - fixed;
                var margin = (sales > 0) ? (sales - cogs) / sales : 0.0;
                var losses = (sales > 0) ? (shrink + cashLoss) / sales : 0.0;
                var tx = (sUnits + aUnits + pre + clr) * c.TX_PER_UNIT / c.DAYS;
                ctrl = this._clamp(c.CTRL0 + pr[4] + oCtrl + mx[2] + cs[1] + sh[3] + rs[2] + pm[6] + clCtrl, 0.0, 100.0);
                var hard = 0;
                for (i = 0; i < this.HARD.length; i++) {
                    if (a[this.HARD[i][0]] === this.HARD[i][1] && p >= this.ROUND_OF[this.HARD[i][0]]) { hard += 1; }
                }
                per.push({ p: p, sales: sales, profit: profit, margin: margin, losses: losses, tx: tx, ctrl: ctrl,
                           pieces: aUnits + pre + clr, left: left, hard: hard, a: a });
                if (p >= k) { break; }
            }
            var last = per[per.length - 1];
            return { per: per, p: last.p, profit: last.profit, margin: last.margin, losses: last.losses, tx: last.tx,
                     ctrl: last.ctrl, left: last.left, hard: last.hard, a: last.a };
        }

        _components(r) {
            var c = this.C;
            var hi = c.P_HI[r.p - 1];
            var pr = this._clamp((r.profit - c.P_LO) / (hi - c.P_LO), 0, 1);
            var m = this._clamp((r.margin - c.M_LO) / (c.M_HI - c.M_LO), 0, 1);
            var l = this._clamp((c.L_LO - r.losses) / (c.L_LO - c.L_HI), 0, 1);
            var s = this._clamp((r.tx - c.S_LO) / (c.S_HI - c.S_LO), 0, 1);
            var k = this._clamp((r.ctrl - c.K_LO) / (c.K_HI - c.K_LO), 0, 1);
            return [pr, m, l, s, k];
        }

        _roundScore(state, period) {
            var c = this.C;
            var m = this._semester(this._flat(state, period), period);
            var comps = this._components(m);
            var w = [c.W_P, c.W_M, c.W_L, c.W_S, c.W_C];
            var tw = 0, num = 0, i;
            for (i = 0; i < 5; i++) { tw += w[i]; num += w[i] * comps[i]; }
            var score = this._clamp(100.0 * num / tw, 0, 100);
            if (m.hard > 0) {
                score = Math.min(score, c.CAP1 - c.CAP_STEP * (m.hard - 1));
            }
            return { score: this._jsround(score), m: m };
        }

        _completed(state) {
            var d = (state && state.decisions) || {};
            var n = 0;
            while (n < this.ROUNDS.length && d['round' + (n + 1)]) { n += 1; }
            return n;
        }

        _composite(state) {
            var n = this._completed(state);
            if (n === 0) { return 0; }
            var w = this.C.PERIOD_WEIGHTS;
            var num = 0, den = 0, p;
            for (p = 1; p <= n; p++) {
                var r = this._roundScore(state, p);
                num += w[p - 1] * r.score;
                den += w[p - 1];
            }
            return this._clamp(this._jsround(num / den), 0, 100);
        }

        _verdictKey(score) {
            if (score >= this.C.THRESH_EXCELLENT) { return 'verdict_excellent'; }
            if (score >= this.C.THRESH_GOOD) { return 'verdict_good'; }
            if (score >= this.C.THRESH_DEVELOPING) { return 'verdict_developing'; }
            return 'verdict_beginner';
        }

        _jsround(x) {
            return (x >= 0) ? Math.floor(x + 0.5) : Math.ceil(x - 0.5);
        }

        _clamp(x, lo, hi) {
            if (x < lo) { return lo; }
            if (x > hi) { return hi; }
            return x;
        }

        _str(id, fallback) {
            var el = document.getElementById(id);
            return (el && el.value) ? el.value : fallback;
        }

        _t(key) {
            var sim = window.mySimulation;
            return (sim && sim.t) ? sim.t(key) : key;
        }

        _lang() {
            var sim = window.mySimulation;
            return (sim && sim.language) ? sim.language : 'en';
        }

        _fmtInt(n) {
            var v = Math.round(Math.abs(n));
            var s = String(v);
            var out = '';
            var i, k = 0;
            for (i = s.length - 1; i >= 0; i--) {
                out = s.charAt(i) + out;
                k += 1;
                if (k % 3 === 0 && i > 0) { out = ',' + out; }
            }
            return (n < 0 && v > 0 ? '-' : '') + out;
        }

        _fmtDec(n) {
            var v = Math.round(n * 10) / 10;
            var whole = Math.floor(Math.abs(v));
            var dec = Math.round((Math.abs(v) - whole) * 10);
            var s = String(whole) + '.' + String(dec);
            return (v < 0 ? '-' : '') + s;
        }

        _fmtPct(n) {
            return (this._lang() === 'es') ? (this._fmtDec(n) + ' %') : (this._fmtDec(n) + '%');
        }

        _fmtUsd(n) {
            var v = Math.round(Math.abs(n));
            return (n < 0 && v > 0 ? '-$' : '$') + this._fmtInt(v);
        }

        _fmtUsd2(n) {
            if (n === null || n === undefined) { return '-'; }
            var v = Math.round(Math.abs(n) * 100);
            var whole = Math.floor(v / 100);
            var cents = v - whole * 100;
            return (n < 0 && v > 0 ? '-$' : '$') + this._fmtInt(whole) + '.' + (cents < 10 ? '0' : '') + String(cents);
        }

        _sum(arr) {
            var s = 0, i;
            for (i = 0; i < arr.length; i++) { s += arr[i]; }
            return s;
        }

        _syncControlsFromDecisions(state) {
            var period = (state && state.currentPeriod) || 1;
            var d = (state && state.decisions) || {};
            var k = d['round' + period] || {};
            (this.CONTROLS[period] || []).forEach(function(key) {
                var el = document.getElementById(key);
                if (el && k[key]) { el.value = k[key]; }
            });
        }

        _set(id, text) {
            var el = document.getElementById(id);
            if (el) { el.textContent = text; }
        }

        _updateBriefing(state, forcedPeriod) {
            if (!state) { return; }
            var ds = state.domainState || {};
            var period = forcedPeriod || state.currentPeriod || 1;
            var done = !!ds.finished;
            var nameEl = document.getElementById('roundName');
            if (nameEl) {
                nameEl.textContent = done ? this._t('round_done')
                    : this._t((this.ROUNDS[period - 1] || this.ROUNDS[0]).nameKey);
            }
            var sH = ds.salesHistory || [];
            var pH = ds.profitHistory || [];
            var mH = ds.marginHistory || [];
            var lH = ds.lossesHistory || [];
            var stH = ds.studentsHistory || [];
            var aH = ds.apparelHistory || [];
            var cH = ds.controlHistory || [];
            var n = sH.length;
            this._set('salesDisplay', n ? (this._fmtUsd(sH[n - 1]) + ' · ' + this._t('txt_year') + ' ' + this._fmtUsd(this._sum(sH))) : '-');
            this._set('profitDisplay', n ? (this._fmtUsd(pH[n - 1]) + ' · ' + this._t('txt_year') + ' ' + this._fmtUsd(this._sum(pH))) : '-');
            this._set('marginDisplay', n ? this._fmtPct(mH[n - 1]) : '-');
            this._set('lossesDisplay', n ? this._fmtPct(lH[n - 1]) : '-');
            this._set('studentsDisplay', n ? this._fmtInt(stH[n - 1]) : '-');
            this._set('apparelDisplay', n ? this._fmtInt(aH[n - 1]) : '-');
            this._set('controlDisplay', n ? this._fmtInt(cH[n - 1]) : '-');
            var sc = (ds.performance && ds.performance.overallScore) || 0;
            this._set('scoreDisplay', String(sc));
            var i;
            for (i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].panel);
                if (panel) { panel.style.display = (!done && (i + 1) === period) ? '' : 'none'; }
            }
            var actions = document.getElementById('actionsRow');
            if (actions) { actions.style.display = done ? 'none' : ''; }
            this._syncControlsFromDecisions(state);
        }

        _fbKey(g, v) {
            var maps = {
                price1: { cost10: 'fb_pr_cost10', keystone: 'fb_pr_keystone', match: 'fb_pr_match', premium: 'fb_pr_premium' },
                order1: { repeat: 'fb_or_repeat', record: 'fb_or_record', bundle: 'fb_or_bundle', none: 'fb_or_none' },
                mix2: { same: 'fb_mx_same', record: 'fb_mx_record', candy: 'fb_mx_candy', wide: 'fb_mx_wide' },
                cash2: { weekly: 'fb_cs_weekly', daily: 'fb_cs_daily', alone: 'fb_cs_alone', force: 'fb_cs_force' },
                shrink3: { ignore: 'fb_sh_ignore', controls: 'fb_sh_controls', lock: 'fb_sh_lock', samples: 'fb_sh_samples' },
                restock3: { none: 'fb_rs_none', sizes: 'fb_rs_sizes', all: 'fb_rs_all', consign: 'fb_rs_consign' },
                promo4: { none: 'fb_pm_none', preorder: 'fb_pm_preorder', half: 'fb_pm_half', class: 'fb_pm_class' },
                close4: { box: 'fb_cl_box', full: 'fb_cl_full', gross: 'fb_cl_gross', retail: 'fb_cl_retail' }
            };
            return (maps[g] && maps[g][v]) ? maps[g][v] : 'fb_next';
        }

        getHint(state, results) {
            var p = (results && results.period) || 1;
            var m = this._semester(this._flat(state, p), p);
            var a = m.a;
            if (m.hard > 0) { return this._t('hint_cap'); }
            var ctl = this.CONTROLS[p] || [];
            var i;
            for (i = 0; i < ctl.length; i++) {
                if (a[ctl[i]] !== this.BEST[ctl[i]]) { return this._t(this._fbKey(ctl[i], a[ctl[i]])); }
            }
            return null;
        }

        getChartConfig() {
            return {
                servedChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Students served a day', data: [], borderColor: '#0f4c5c', backgroundColor: 'rgba(15,76,92,0.12)', borderWidth: 2 },
                            { label: 'Controls and trust', data: [], borderColor: '#8a4b0c', backgroundColor: 'rgba(138,75,12,0.12)', borderWidth: 2 }
                        ]
                    },
                    options: { responsive: true, scales: { y: { beginAtZero: true, max: 350 } } }
                },
                scoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Round score', data: [], borderColor: '#0f4c5c', backgroundColor: 'rgba(15,76,92,0.35)', borderWidth: 1 }
                        ]
                    },
                    options: { responsive: true, scales: { y: { beginAtZero: true, max: 100 } } }
                }
            };
        }

        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var studentsHistory = ds.studentsHistory || [];
            var controlHistory = ds.controlHistory || [];
            var scoreHistory = ds.scoreHistory || [];
            var self = this;
            var labels = studentsHistory.map(function(x, i) { return self._t('round_label_short') + (i + 1); });
            return {
                servedChart: {
                    labels: labels,
                    datasets: [
                        { data: studentsHistory.slice(), label: this._t('chart_students') },
                        { data: controlHistory.slice(), label: this._t('chart_control') }
                    ]
                },
                scoreChart: {
                    labels: scoreHistory.map(function(x, i) { return self._t('round_label_short') + (i + 1); }),
                    datasets: [
                        { data: scoreHistory.slice(), label: this._t('chart_score') }
                    ]
                }
            };
        }

        getHistoryTableConfig() {
            var self = this;
            var pct = function(v) { return self._fmtPct(v); };
            var usd = function(v) { return self._fmtUsd(v); };
            var intf = function(v) { return self._fmtInt(v); };
            return [
                { key: 'results.sales', label: 'Sales', i18nKey: 'col_sales', formatter: usd },
                { key: 'results.profit', label: 'Profit', i18nKey: 'col_profit', formatter: usd },
                { key: 'results.margin', label: 'Gross margin', i18nKey: 'col_margin', formatter: pct },
                { key: 'results.losses', label: 'Shrink and cash losses', i18nKey: 'col_losses', formatter: pct },
                { key: 'results.students', label: 'Students served a day', i18nKey: 'col_students', formatter: intf },
                { key: 'results.apparel', label: 'Apparel sold', i18nKey: 'col_apparel', formatter: intf },
                { key: 'results.control', label: 'Controls and trust', i18nKey: 'col_control', formatter: intf },
                { key: 'results.roundScore', label: 'Round score', i18nKey: 'col_score' }
            ];
        }

        getPerformanceSummary(history) {
            var state = window.mySimulation.state;
            var n = this._completed(state);
            var mm = Math.max(1, n);
            var m = this._semester(this._flat(state, mm), mm);
            var composite = this._composite(state);
            var insights = [];
            var self = this;
            var d = this._flat(state, mm);
            var shown = this.KEYS.filter(function(g) { return self.ROUND_OF[g] <= mm; });
            shown.forEach(function(g) { insights.push(self._t(self._fbKey(g, self._active(d, mm, g)))); });
            if (m.hard > 0) { insights.push(this._t('cm_cap')); }
            insights.push(this._t('fb_next'));
            var vk = this._verdictKey(composite);
            var sales = m.per.map(function(x) { return Math.round(x.sales); });
            var profits = m.per.map(function(x) { return Math.round(x.profit); });
            return {
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                performance: vk.replace('verdict_', ''),
                performanceLabel: this._t(vk),
                sales: this._sum(sales),
                profit: this._sum(profits),
                students: Math.round(m.tx),
                losses: Math.round(m.losses * 1000) / 10,
                control: Math.round(m.ctrl),
                left: Math.round(m.left),
                hard: m.hard,
                periods: (history || []).length,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var items = (s.insights || []).map(function(x) { return '<li>' + x + '</li>'; }).join('');
            return '<div class="ej2248-cm">'
                + '<div class="ej2248-cm-score">' + score + '<span class="ej2248-cm-max">/100</span></div>'
                + '<div class="ej2248-cm-verdict">' + (s.performanceLabel || '') + '</div>'
                + '<div class="ej2248-cm-kpis">'
                + '<div class="ej2248-cm-kpi">' + this._t('cm_kpi_sales') + ' <strong>' + this._fmtUsd(s.sales || 0) + '</strong></div>'
                + '<div class="ej2248-cm-kpi">' + this._t('cm_kpi_profit') + ' <strong>' + this._fmtUsd(s.profit || 0) + '</strong></div>'
                + '<div class="ej2248-cm-kpi">' + this._t('cm_kpi_students') + ' <strong>' + this._fmtInt(s.students || 0) + '</strong></div>'
                + '<div class="ej2248-cm-kpi">' + this._t('cm_kpi_losses') + ' <strong>' + this._fmtPct(s.losses || 0) + '</strong></div>'
                + '<div class="ej2248-cm-kpi">' + this._t('cm_kpi_control') + ' <strong>' + this._fmtInt(s.control || 0) + '</strong></div>'
                + '<div class="ej2248-cm-kpi">' + this._t('cm_kpi_left') + ' <strong>' + this._fmtInt(s.left || 0) + '</strong></div>'
                + '</div>'
                + '<div class="ej2248-cm-debrief">' + this._t('cm_debrief') + '</div>'
                + '<ul class="ej2248-cm-insights">' + items + '</ul>'
                + '</div>';
        }

